mapper.select:
SELECT FRM_UNQ_KY_VAL, DIVS_CD, PPCD, FRM_CFY, CASE WHEN A.FRM_CFY = 'JOB' THEN '작업전' WHEN A.FRM_CFY = 'OZR' THEN '일반' WHEN A.FRM_CFY = 'PDF' THEN '필기' ELSE '' END AS FRM_CFY_NM, FRM_NM, HOLD_SCCD, USER_OFCD, OPPB_CFY, REGPR_ID, REGPR_NM, RG_DT, TO_CHAR(RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_ETCFRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL) AS ATFL_PHCL_NM, (SELECT ATFL_ORSRC_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_ETCFRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL) AS ATFL_ORSRC_NM FROM GE_MP_ETCFRM_M A WHERE DLT_YN = 'N'
AND OPPB_CFY IN ('공통','부서')
AND A.REGPR_ID = #{REGPR_ID}
AND (A.REGPR_ID = #{REGPR_ID} OR OPPB_CFY IN ('공통','부서'))
AND A.PPCD = #{PPCD}
AND A.FRM_CFY = #{FRM_CFY}
AND A.FRM_NM LIKE '%'||#{FRM_NM}||'%'
AND A.REGPR_NM LIKE '%'||#{REGPR_NM}||'%'
ORDER BY RG_DT DESC

mapper.update:
UPDATE GE_MP_ETCFRM_M
   SET FRM_NM = #{FRM_NM},
       OPPB_CFY = #{OPPB_CFY}
 WHERE FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
